import{_ as e,o as a,c as i,l as s,t as o,N as n}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"git-describe | x-cmd man (git man1) | Give an object a human readable name based on an\\navailable ref","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-describe - Give an object a human readable name based on an\\navailable ref","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-describe | x-cmd man (git man1) | Give an object a human readable name based on an\\navailable ref"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-describe - Give an object a human readable name based on an\\navailable ref"}]]},"headers":[],"params":{"isMan":true,"man":"git-describe","category":"git man1","desc":"Give an object a human readable name based on an\\navailable ref"},"relativePath":"git/man1/git-describe.md","filePath":"git/man1/git-describe.md"}'),r={name:"git/man1/git-describe.md"},h={class:"visually-hidden"},l=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-describe - Give an object a human readable name based on an available ref</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--all] [--tags] [--contains] [--abbrev</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">commit-ish</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--all] [--tags] [--contains] [--abbrev</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] --dirty[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mark</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">blo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The command finds the most recent tag that is reachable from a commit. If the tag points to the commit, then only the tag is shown. Otherwise, it suffixes the tag name with the number of additional commits on top of the tagged object and the abbreviated object name of the most recent commit. The result is a &quot;human-readable&quot; object name which can also be used to identify the commit to other git commands.</p><p>By default (without --all or --tags) <strong>git describe</strong> only shows annotated tags. For more information about creating annotated tags see the -a and -s options to <strong>git-tag</strong>(1).</p><p>If the given object refers to a blob, it will be described as <strong>&lt;commit-ish&gt;:&lt;path&gt;</strong>, such that the blob can be found at <strong>&lt;path&gt;</strong> in the <strong>&lt;commit-ish&gt;</strong>, which itself describes the first commit in which this blob occurs in a reverse revision walk from HEAD.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;commit-ish&gt;...</p><blockquote><p>Commit-ish object names to describe. Defaults to HEAD if omitted.</p></blockquote><p>--dirty[=&lt;mark&gt;], --broken[=&lt;mark&gt;]</p><blockquote><p>Describe the state of the working tree. When the working tree matches HEAD, the output is the same as &quot;git describe HEAD&quot;. If the working tree has local modification &quot;-dirty&quot; is appended to it. If a repository is corrupt and Git cannot determine if there is local modification, Git will error out, unless &quot;--broken&quot; is given, which appends the suffix &quot;-broken&quot; instead.</p></blockquote><p>--all</p><blockquote><p>Instead of using only the annotated tags, use any ref found in <strong>refs/</strong> namespace. This option enables matching any known branch, remote-tracking branch, or lightweight tag.</p></blockquote><p>--tags</p><blockquote><p>Instead of using only the annotated tags, use any tag found in <strong>refs/tags</strong> namespace. This option enables matching a lightweight (non-annotated) tag.</p></blockquote><p>--contains</p><blockquote><p>Instead of finding the tag that predates the commit, find the tag that comes after the commit, and thus contains it. Automatically implies --tags.</p></blockquote><p>--abbrev=&lt;n&gt;</p><blockquote><p>Instead of using the default number of hexadecimal digits (which will vary according to the number of objects in the repository with a default of 7) of the abbreviated object name, use &lt;n&gt; digits, or as many digits as needed to form a unique object name. An &lt;n&gt; of 0 will suppress long format, only showing the closest tag.</p></blockquote><p>--candidates=&lt;n&gt;</p><blockquote><p>Instead of considering only the 10 most recent tags as candidates to describe the input commit-ish consider up to &lt;n&gt; candidates. Increasing &lt;n&gt; above 10 will take slightly longer but may produce a more accurate result. An &lt;n&gt; of 0 will cause only exact matches to be output.</p></blockquote><p>--exact-match</p><blockquote><p>Only output exact matches (a tag directly references the supplied commit). This is a synonym for --candidates=0.</p></blockquote><p>--debug</p><blockquote><p>Verbosely display information about the searching strategy being employed to standard error. The tag name will still be printed to standard out.</p></blockquote><p>--long</p><blockquote><p>Always output the long format (the tag, the number of commits and the abbreviated commit name) even when it matches a tag. This is useful when you want to see parts of the commit object name in &quot;describe&quot; output, even when the commit in question happens to be a tagged version. Instead of just emitting the tag name, it will describe such a commit as v1.2-0-gdeadbee (0th commit since tag v1.2 that points at object deadbee....).</p></blockquote><p>--match &lt;pattern&gt;</p><blockquote><p>Only consider tags matching the given <strong>glob(7)</strong> pattern, excluding the &quot;refs/tags/&quot; prefix. If used with <strong>--all</strong>, it also considers local branches and remote-tracking references matching the pattern, excluding respectively &quot;refs/heads/&quot; and &quot;refs/remotes/&quot; prefix; references of other types are never considered. If given multiple times, a list of patterns will be accumulated, and tags matching any of the patterns will be considered. Use <strong>--no-match</strong> to clear and reset the list of patterns.</p></blockquote><p>--exclude &lt;pattern&gt;</p><blockquote><p>Do not consider tags matching the given <strong>glob(7)</strong> pattern, excluding the &quot;refs/tags/&quot; prefix. If used with <strong>--all</strong>, it also does not consider local branches and remote-tracking references matching the pattern, excluding respectively &quot;refs/heads/&quot; and &quot;refs/remotes/&quot; prefix; references of other types are never considered. If given multiple times, a list of patterns will be accumulated and tags matching any of the patterns will be excluded. When combined with --match a tag will be considered when it matches at least one --match pattern and does not match any of the --exclude patterns. Use <strong>--no-exclude</strong> to clear and reset the list of patterns.</p></blockquote><p>--always</p><blockquote><p>Show uniquely abbreviated commit object as fallback.</p></blockquote><p>--first-parent</p><blockquote><p>Follow only the first parent commit upon seeing a merge commit. This is useful when you wish to not match tags on branches merged in the history of the target commit.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>With something like git.git current tree, I get:</p><blockquote><pre><code>[torvalds@g5 git]$ git describe parent
v1.0.4-14-g2414721
</code></pre></blockquote><p>i.e. the current head of my &quot;parent&quot; branch is based on v1.0.4, but since it has a few commits on top of that, describe has added the number of additional commits (&quot;14&quot;) and an abbreviated object name for the commit itself (&quot;2414721&quot;) at the end.</p><p>The number of additional commits is the number of commits which would be displayed by &quot;git log v1.0.4..parent&quot;. The hash suffix is &quot;-g&quot; + an unambigous abbreviation for the tip commit of parent (which was <strong>2414721b194453f058079d897d13c4e377f92dc6</strong>). The length of the abbreviation scales as the repository grows, using the approximate number of objects in the repository and a bit of math around the birthday paradox, and defaults to a minimum of 7. The &quot;g&quot; prefix stands for &quot;git&quot; and is used to allow describing the version of a software depending on the SCM the software is managed with. This is useful in an environment where people may use different SCMs.</p><p>Doing a <em>git describe</em> on a tag-name will just show the tag name:</p><blockquote><pre><code>[torvalds@g5 git]$ git describe v1.0.4
v1.0.4
</code></pre></blockquote><p>With --all, the command can use branch heads as references, so the output shows the reference path as well:</p><blockquote><pre><code>[torvalds@g5 git]$ git describe --all --abbrev=4 v1.0.5^2
tags/v1.0.0-21-g975b
</code></pre></blockquote><blockquote><pre><code>[torvalds@g5 git]$ git describe --all --abbrev=4 HEAD^
heads/lt/describe-7-g975b
</code></pre></blockquote><p>With --abbrev set to 0, the command can be used to find the closest tagname without any suffix:</p><blockquote><pre><code>[torvalds@g5 git]$ git describe --abbrev=0 v1.0.5^2
tags/v1.0.0
</code></pre></blockquote><p>Note that the suffix you get if you type these commands today may be longer than what Linus saw above when he ran these commands, as your Git repository may have new commits whose object names begin with 975b that did not exist back then, and &quot;-g975b&quot; suffix alone may not be sufficient to disambiguate these commits.</p><h2 id="search-strategy" tabindex="-1">SEARCH STRATEGY <a class="header-anchor" href="#search-strategy" aria-label="Permalink to &quot;SEARCH STRATEGY&quot;">​</a></h2><p>For each commit-ish supplied, <em>git describe</em> will first look for a tag which tags exactly that commit. Annotated tags will always be preferred over lightweight tags, and tags with newer dates will always be preferred over tags with older dates. If an exact match is found, its name will be output and searching will stop.</p><p>If an exact match was not found, <em>git describe</em> will walk back through the commit history to locate an ancestor commit which has been tagged. The ancestor&#39;s tag will be output along with an abbreviation of the input commit-ish&#39;s SHA-1. If <strong>--first-parent</strong> was specified then the walk will only consider the first parent of each commit.</p><p>If multiple tags were found during the walk then the tag which has the fewest commits different from the input commit-ish will be selected and output. Here fewest commits different is defined as the number of commits which would be shown by <strong>git log tag..input</strong> will be the smallest number of commits possible.</p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Tree objects as well as tag objects not pointing at commits, cannot be described. When describing blobs, the lightweight tags pointing at blobs are ignored, but the blob is still described as &lt;committ-ish&gt;:&lt;path&gt; despite the lightweight tag being favorable.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,58);function c(t,d,g,p,m,b){return a(),i("div",null,[s("h1",h,o(t.$params.man),1),l])}const k=e(r,[["render",c]]);export{f as __pageData,k as default};
